Configuration:
publicResource: false
supportCredentials: false
originGroups: [
  {
    "name": "Default group",
    "origins": [
      "*"
    ],
    "accessControlMaxAge": 30,
    "allowedMethods": [
      {
        "methodName": "GET",
        "isAllowed": true
      },
      {
        "methodName": "POST",
        "isAllowed": true
      },
      {
        "methodName": "PUT",
        "isAllowed": true
      },
      {
        "methodName": "PATCH",
        "isAllowed": true
      },
      {
        "methodName": "DELETE",
        "isAllowed": true
      },
      {
        "methodName": "CONNECT",
        "isAllowed": true
      },
      {
        "methodName": "TRACE",
        "isAllowed": true
      },
      {
        "methodName": "OPTIONS",
        "isAllowed": true
      }
    ],
    "headers": [
      "Content-Type",
      "client_id",
      "client_secret",
      "Authorization",
      "X-API-Key",
      "X-Auth-Token",
      "X-Request-ID",
      "Accept",
      "Origin"
    ],
    "exposedHeaders": [
      "x-llm-proxy-llm-model",
      "x-llm-proxy-llm-provider",
      "x-llm-proxy-routing-fallback",
      "x-llm-proxy-routing-type",
      "x-ratelimit-limit-requests",
      "x-ratelimit-limit-tokens",
      "x-ratelimit-remaining-requests",
      "x-ratelimit-remaining-tokens",
      "x-llm-proxy-semantic-routing-success",
      "x-llm-proxy-ratelimit",
      "x-llm-proxy-request-success",
      "x-llm-proxy-semantic-guard-success",
      "x-llm-proxy-model-based-routing-success",
      "openai-processing-ms",
      "x-correlation-id"
    ]
  }
]
